_EXPECTED_LOCALES = {code for code, _label in LANGUAGE_OPTIONS if code != "en"}
if set(_METADATA_ROWS) != _EXPECTED_LOCALES:
    raise ValueError(
        "Help-hub metadata catalogs must cover every non-English locale"
    )
if len(HELP_HUB_METADATA_KEYS) != 28 or len(set(HELP_HUB_METADATA_KEYS)) != 28:
    raise ValueError("Help-hub metadata sources must be exactly 28 unique keys")

HELP_HUB_METADATA_CATALOGS: dict[str, dict[str, str]] = {
    locale: dict(zip(HELP_HUB_METADATA_KEYS, row.split("|"), strict=True))
    for locale, row in _METADATA_ROWS.items()
}

for _locale, _entries in HELP_HUB_METADATA_CATALOGS.items():
    if set(_entries) != set(HELP_HUB_METADATA_KEYS):
        raise ValueError(
            f"Help-hub metadata source coverage is incomplete: {_locale}"
        )
    for _source, _translation in _entries.items():
        if not _translation.strip() or _translation == _source:
            raise ValueError(
                f"Missing help-hub metadata translation: {_locale}: {_source}"
            )
        if Counter(
            re.findall(r"\{([A-Za-z][A-Za-z0-9_]*)\}", _source)
        ) != Counter(re.findall(r"\{([A-Za-z][A-Za-z0-9_]*)\}", _translation)):
            raise ValueError(
                f"Help-hub metadata template slots differ: {_locale}: {_source}"
            )
